public class GymForm { @NotNull private Long cityId; @NotBlank @Size(max=150) private String name; @NotBlank @Size(max=3000) private String description; @NotBlank @Size(max=300) private String address; private BigDecimal latitude; private BigDecimal longitude; @Size(max=50) private String phone; @Size(max=500) private String websiteUrl; @Size(max=1000) private String openingHours; @Size(max=1500) private String services; @Size(max=1000) private String priceInfo; @NotNull private ContentStatus status=ContentStatus.DRAFT; public Long getCityId(){return cityId;} public void setCityId(Long v){cityId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getWebsiteUrl(){return websiteUrl;} public void setWebsiteUrl(String v){websiteUrl=v;} public String getOpeningHours(){return openingHours;} public void setOpeningHours(String v){openingHours=v;} public String getServices(){return services;} public void setServices(String v){services=v;} public String getPriceInfo(){return priceInfo;} public void setPriceInfo(String v){priceInfo=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;} }
